{
  "name": "@papersflow/opencode-papersflow",
  "version": "1.0.0",
  "description": "OpenCode plugin for academic research — search 474M+ papers, verify citations, explore citation graphs, and run deep research via PapersFlow",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "files": ["dist"],
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "prepublishOnly": "npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "research",
    "academic",
    "citation",
    "papers",
    "literature-search",
    "mcp",
    "papersflow"
  ],
  "author": {
    "name": "PapersFlow",
    "email": "developer@papersflow.ai"
  },
  "homepage": "https://papersflow.ai",
  "repository": {
    "type": "git",
    "url": "https://github.com/papersflow-ai/opencode-papersflow"
  },
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=0.15.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": ">=0.15.0",
    "typescript": ">=5.0.0"
  }
}
